#!/bin/bash
# ============================================================================
# add_doctor_surgery_dashboard.sh
#
# Adds a dedicated Surgery Dashboard for doctors, separate from the existing
# OPD Doctor Dashboard.
#
#   NEW:      app/(main)/doctor-dashboard-surgery/actions.js
#   NEW:      app/(main)/doctor-dashboard-surgery/page.js
#   MODIFIED: app/(main)/doctor-dashboard/page.js        (adds "Surgery
#             Dashboard" toggle button next to the existing tab strip)
#   MODIFIED: app/components/AppShell.js                 (adds sidebar nav
#             item + page title entry)
#
# Surgery Dashboard has 3 tabs, all derived from existing status fields
# (ot_schedule.status, recovery_episodes.discharge_date) -- no schema
# changes, no new tables:
#   Scheduled -- ot_schedule.status = 'Scheduled', all upcoming dates
#   Active    -- 'In Progress' (checked-in/in OT) + 'Completed' cases still
#                in recovery (discharge_date IS NULL)
#   History   -- recovery_episodes.discharge_date IS NOT NULL
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Doctor Surgery Dashboard deploy script"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

mkdir -p "app/(main)/doctor-dashboard-surgery"

echo "==> Writing app/(main)/doctor-dashboard-surgery/actions.js (new file)"
echo "" | base64 -d > "app/(main)/doctor-dashboard-surgery/actions.js"

echo "==> Writing app/(main)/doctor-dashboard-surgery/page.js (new file)"
echo "" | base64 -d > "app/(main)/doctor-dashboard-surgery/page.js"

echo "==> Overwriting app/(main)/doctor-dashboard/page.js (adds Surgery Dashboard toggle button)"
echo "" | base64 -d > "app/(main)/doctor-dashboard/page.js"

echo "==> Overwriting app/components/AppShell.js (adds sidebar item + page title)"
echo "" | base64 -d > "app/components/AppShell.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Add Doctor Surgery Dashboard (Scheduled/Active/History) separate from OPD dashboard"'
echo "    git push"
